// Fetch the Structurizr DSL WorkspaceParser source to understand feature flag handling
const res = await fetch("https://raw.githubusercontent.com/structurizr/structurizr-dsl/main/src/main/java/com/structurizr/dsl/WorkspaceParser.java");
const text = await res.text();
// Find the !docs handling and feature flag logic
const lines = text.split("\n");
const relevant = [];
for (let i = 0; i < lines.length; i++) {
  if (lines[i].includes("!docs") || lines[i].includes("FeatureFlags") || lines[i].includes("featureFlags") || lines[i].includes("DSL_DOCUMENTATION")) {
    relevant.push(`${i+1}: ${lines[i]}`);
  }
}
return { status: res.status, relevant };

