// Query the MCP server directly for tool descriptions
async function mcpPost(body, sessionId) {
  const headers = { "Content-Type": "application/json", "Accept": "application/json, text/event-stream" };
  if (sessionId) headers["Mcp-Session-Id"] = sessionId;
  const res = await fetch("http://172.21.0.2:8181/mcp", { method: "POST", headers, body: JSON.stringify(body) });
  const text = await res.text();
  return { status: res.status, headers: Object.fromEntries(res.headers.entries()), text };
}

// Initialize
const init = await mcpPost({ jsonrpc: "2.0", id: 1, method: "initialize", params: { protocolVersion: "2025-03-26", capabilities: {}, clientInfo: { name: "probe", version: "1.0" } } });
const sessionId = init.headers["mcp-session-id"];
return { init: init.text.slice(0, 2000), sessionId };

