const dsl = `workspace "Order Service" "Multi-file Structurizr workspace assembled with !include, documented with !docs" {

    !identifiers hierarchical

    model {
        customer = person "Customer" "A customer who places orders and tracks their status"
        support = person "Support Agent" "A support agent who looks up order status on behalf of customers"

        orders = softwareSystem "Order Service" "Accepts and tracks customer orders end to end" {
            web = container "Web Application" "Server-rendered storefront and order tracking UI" "TypeScript/React" "Web"
            api = container "Order API" "REST API for creating and querying orders" "Go" "API"
            db = container "Order Database" "System of record for orders and line items" "PostgreSQL 16" "Database"
            queue = container "Message Queue" "Buffers order events for asynchronous processing" "RabbitMQ" "Queue"
            worker = container "Order Worker" "Processes order events and updates order state" "Go" "Worker"
        }

        payments = softwareSystem "Payment Provider" "External payment gateway that authorizes and captures card payments" "External"

        customer -> orders.web "places orders and tracks status in" "HTTPS"
        support -> orders.web "looks up order status in" "HTTPS"
        orders.web -> orders.api "calls" "HTTPS/JSON"
        orders.api -> orders.db "reads from and writes to" "SQL"
        orders.api -> orders.queue "publishes order events to" "AMQP" "Async"
        orders.worker -> orders.queue "consumes order events from" "AMQP" "Async"
        orders.worker -> orders.db "updates order state in" "SQL"
        orders.api -> payments "authorizes and captures payments via" "HTTPS/JSON"
    }

    views {
        systemLandscape "Landscape" {
            include *
            autoLayout
            title "System Landscape"
        }

        systemContext orders "Context" {
            include *
            autoLayout
            title "System Context for Order Service"
        }

        container orders "Containers" {
            include *
            autoLayout
            title "Containers for Order Service"
        }

        dynamic orders "OrderFlow" "Placing an order" {
            customer -> orders.web "submits an order" "HTTPS"
            orders.web -> orders.api "creates the order" "HTTPS/JSON"
            orders.api -> payments "authorizes the payment" "HTTPS/JSON"
            orders.api -> orders.queue "publishes an order event" "AMQP"
            orders.worker -> orders.queue "consumes the order event" "AMQP"
            orders.worker -> orders.db "marks the order as confirmed" "SQL"
            autoLayout
            title "Placing an Order"
        }

        styles {
            element "Person" {
                shape Person
                background #08427B
                color #ffffff
            }
            element "Software System" {
                background #1168BD
                color #ffffff
            }
            element "External" {
                background #999999
                color #ffffff
            }
            element "Container" {
                background #438DD5
                color #ffffff
            }
            element "Database" {
                shape Cylinder
            }
            element "Queue" {
                shape Pipe
            }
            element "Web" {
                shape WebBrowser
            }
            element "Worker" {
                shape Robot
            }
            relationship "Relationship" {
                routing Orthogonal
            }
            relationship "Async" {
                style dashed
            }
        }
    }

    configuration {
        scope softwareSystem
    }
}`;
const [parsed, validated, inspected] = await Promise.allSettled([
  tools.structurizr.parse({ dsl }),
  tools.structurizr.validate({ dsl }),
  tools.structurizr.inspect({ dsl })
]);
const summarize = (r) => r.status === "fulfilled" ? r.value : { error: String(r.reason) };
const p = summarize(parsed);
return {
  parse: {
    ok: p.ok !== undefined ? p.ok : true,
