    containers: p.model?.softwareSystems?.[0]?.containers?.length,
    views: {
      landscape: p.views?.systemLandscapeViews?.length,
      context: p.views?.systemContextViews?.length,
      container: p.views?.containerViews?.length,
      dynamic: p.views?.dynamicViews?.length
    }
  },
  validate: summarize(validated),
  inspect: summarize(inspected)
};

